CREATE OR REPLACE FUNCTION public.newsletter_city_readers(p_city uuid) RETURNS int LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$ SELECT count(*)::int FROM public.newsletter_subscribers WHERE city_id = p_city AND is_active $$;
CREATE OR REPLACE FUNCTION public.newsletter_city_price_cents(p_city uuid) RETURNS int LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$ SELECT greatest(2000, ceil(public.newsletter_city_readers(p_city) * 3000 / 1000.0)::int) $$;
CREATE OR REPLACE FUNCTION public.newsletter_city_taken(p_city uuid, p_date date) RETURNS int LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$ SELECT count(*)::int FROM public.newsletter_placements WHERE target_city_id = p_city AND edition_date = p_date AND (status IN ('paid', 'approved', 'published') OR (status = 'pending_payment' AND created_at > now() - interval '30 minutes')) $$;
CREATE OR REPLACE FUNCTION public.newsletter_city_editions(p_city uuid) RETURNS TABLE (edition_date date, places_left int, readers int, price_cents int) LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$ WITH nxt AS (SELECT (current_date + 2 + ((2 - extract(isodow FROM current_date + 2)::int + 7) % 7))::date AS d) SELECT (nxt.d + 7 * g)::date, greatest(0, 4 - public.newsletter_city_taken(p_city, (nxt.d + 7 * g)::date)), public.newsletter_city_readers(p_city), public.newsletter_city_price_cents(p_city) FROM nxt, generate_series(0, 5) g $$;
GRANT EXECUTE ON FUNCTION public.newsletter_city_editions(uuid) TO authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.newsletter_city_price_cents(uuid) TO authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.newsletter_city_taken(uuid, date) TO service_role;
CREATE OR REPLACE FUNCTION public.is_owner_pro(_user_id uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$ SELECT EXISTS (SELECT 1 FROM public.owner_pro_subscriptions WHERE user_id = _user_id AND status = 'active' AND (current_period_end IS NULL OR current_period_end > now())) OR EXISTS (SELECT 1 FROM public.package_orders o WHERE o.user_id = _user_id AND o.package IN ('groei', 'dominant') AND public.founding_partner_live(o.status)); $$;
CREATE OR REPLACE FUNCTION public.release_bundle_event(p_event uuid) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ DECLARE v_restaurant uuid; BEGIN SELECT restaurant_id INTO v_restaurant FROM public.restaurant_events WHERE id = p_event; IF v_restaurant IS NULL OR NOT public.promo_can_manage(v_restaurant) THEN RAISE EXCEPTION 'Alleen de geverifieerde eigenaar' USING ERRCODE = '42501'; END IF; IF NOT EXISTS (SELECT 1 FROM public.package_orders o WHERE o.restaurant_id = v_restaurant AND o.package IN ('groei', 'dominant') AND public.founding_partner_live(o.status)) THEN RAISE EXCEPTION 'Dit hoort bij Groei en Dominant' USING ERRCODE = 'P0001'; END IF; IF EXISTS (SELECT 1 FROM public.restaurant_events e WHERE e.restaurant_id = v_restaurant AND e.id <> p_event AND e.promotion_status = 'comped' AND e.released_by IS NULL AND coalesce(e.paid_until, now()) > now()) THEN RAISE EXCEPTION 'Je evenement van deze maand loopt al. Zet het eerst stop of koop een extra evenement.' USING ERRCODE = 'P0001'; END IF; UPDATE public.restaurant_events SET promotion_status = 'comped', released_at = coalesce(released_at, now()), released_by = NULL, paid_until = (date_trunc('month', now()) + interval '1 month') WHERE id = p_event; RETURN true; END $$;
REVOKE ALL ON FUNCTION public.release_bundle_event(uuid) FROM public, anon;
GRANT EXECUTE ON FUNCTION public.release_bundle_event(uuid) TO authenticated;
CREATE OR REPLACE FUNCTION public.request_test_visit(p_restaurant uuid, p_note text DEFAULT NULL) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ DECLARE v_id uuid; BEGIN IF auth.uid() IS NULL OR NOT public.is_verified_owner(auth.uid(), p_restaurant) THEN RAISE EXCEPTION 'Claim eerst je restaurant' USING ERRCODE = '42501'; END IF; IF EXISTS (SELECT 1 FROM public.test_visit_requests WHERE restaurant_id = p_restaurant AND status IN ('requested', 'planned', 'visited')) THEN RAISE EXCEPTION 'Je aanvraag loopt nog' USING ERRCODE = 'P0001'; END IF; IF (SELECT count(*) FROM public.test_visit_requests WHERE restaurant_id = p_restaurant AND status <> 'withdrawn' AND created_at > now() - interval '12 months') >= 2 THEN RAISE EXCEPTION 'Je kunt twee keer per jaar een testbezoek aanvragen' USING ERRCODE = 'P0001'; END IF; IF EXISTS (SELECT 1 FROM public.test_visit_requests WHERE restaurant_id = p_restaurant AND status = 'rejected' AND coalesce(decided_at, created_at) > now() - interval '6 months') THEN RAISE EXCEPTION 'Na een afwijzing kun je na 6 maanden opnieuw een aanvraag doen' USING ERRCODE = 'P0001'; END IF; INSERT INTO public.test_visit_requests (restaurant_id, user_id, owner_note) VALUES (p_restaurant, auth.uid(), nullif(left(trim(coalesce(p_note, '')), 500), '')) RETURNING id INTO v_id; RETURN v_id; END $$;
REVOKE ALL ON FUNCTION public.request_test_visit(uuid, text) FROM public, anon;
GRANT EXECUTE ON FUNCTION public.request_test_visit(uuid, text) TO authenticated;
CREATE OR REPLACE FUNCTION public.my_test_visits(p_restaurant uuid) RETURNS TABLE (id uuid, status text, feedback text, visited_on date, created_at timestamptz, decided_at timestamptz) LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$ SELECT t.id, t.status, t.feedback, t.visited_on, t.created_at, t.decided_at FROM public.test_visit_requests t WHERE t.restaurant_id = p_restaurant AND auth.uid() IS NOT NULL AND public.is_verified_owner(auth.uid(), p_restaurant) ORDER BY t.created_at DESC LIMIT 10 $$;
GRANT EXECUTE ON FUNCTION public.my_test_visits(uuid) TO authenticated;
CREATE OR REPLACE FUNCTION public.city_tested_restaurants(p_city uuid) RETURNS TABLE (restaurant_id uuid, tested_at date, reason text, collection_slug text, collection_title text) LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$ SELECT DISTINCT ON (cr.restaurant_id) cr.restaurant_id, cr.tested_at, cr.featured_reason, c.slug, c.title FROM public.collection_restaurants cr JOIN public.collections c ON c.id = cr.collection_id AND c.is_active JOIN public.restaurants r ON r.id = cr.restaurant_id AND r.is_active WHERE cr.tested_at IS NOT NULL AND r.city_id = p_city ORDER BY cr.restaurant_id, cr.tested_at DESC $$;
GRANT EXECUTE ON FUNCTION public.city_tested_restaurants(uuid) TO anon, authenticated;